List<Booking> bookings = new ArrayList<>();
bookings.add(new Booking("anna@example.com", "Budapest", 3));
bookings.add(new Booking("bela@example.com", "Vienna", 1));

Booking first = bookings.get(0);   // constant time, no walk
int rows = bookings.size();        // 2

List<Booking> bookings = new ArrayList<>(List.of(
        new Booking("Anna", 3),
        new Booking("Bela", 0),
        new Booking("Csilla", 2)));

// Drop invalid rows before the report runs.
bookings.removeIf(b -> b.nights() == 0);
System.out.println(bookings.size());   // 2

List<Booking> bookings = new ArrayList<>(rows);

// City ascending, then revenue descending, then hotel name.
bookings.sort(Comparator
        .comparing(Booking::city)
        .thenComparing(Comparator.comparingInt(Booking::total).reversed())
        .thenComparing(Booking::hotelName));

bookings.forEach(b -> System.out.println(b.hotelName()));

List<String> cities = List.of("Budapest", "Vienna", "Praha");
// cities.add("Rome");   // UnsupportedOperationException

// A mutable copy when the report needs to sort or edit it.
List<String> editable = new ArrayList<>(cities);
editable.add("Rome");

LinkedList<Booking> line = new LinkedList<>();
line.addLast(new Booking("Anna", 3));
line.addLast(new Booking("Bela", 1));

Booking next = line.removeFirst();   // Anna, constant time
Booking last = line.removeLast();    // Bela
System.out.println(line.size());     // 0

Map<String, Integer> nightsByCity = new HashMap<>();
nightsByCity.put("Budapest", 12);
nightsByCity.put("Vienna", 7);

int nights = nightsByCity.get("Budapest");   // 12
boolean hasPraha = nightsByCity.containsKey("Praha");   // false
System.out.println(nightsByCity);

Map<String, Integer> countByCity = new HashMap<>();
countByCity.put("Budapest", 3);

// Missing keys count as zero, so no branch is needed.
int vienna = countByCity.getOrDefault("Vienna", 0);
System.out.println(vienna);   // 0

Map<String, List<Booking>> byCity = new HashMap<>();

for (Booking b : bookings) {
    // The list is created once per city, then reused.
    byCity.computeIfAbsent(b.city(), key -> new ArrayList<>()).add(b);
}

System.out.println(byCity.get("Budapest").size());

Map<String, Integer> revenueByHotel = new HashMap<>();

for (Booking b : bookings) {
    revenueByHotel.merge(b.hotelName(), b.total(), Integer::sum);
}

// Danube View appears three times, the values are added.
System.out.println(revenueByHotel.get("Danube View"));

Map<String, Integer> revenue = new TreeMap<>();
revenue.put("Danube View", 640);
revenue.put("City Inn", 180);

for (Map.Entry<String, Integer> entry : revenue.entrySet()) {
    System.out.printf("%-12s %5d%n", entry.getKey(), entry.getValue());
}

int total = 0;
for (int value : revenue.values()) {
    total += value;
}

// Keys must be Comparable, or pass a Comparator to the constructor.
TreeMap<Integer, Long> byYear = new TreeMap<>();
byYear.put(2024, 57L);
byYear.put(2023, 41L);

System.out.println(byYear.firstKey());        // 2023
System.out.println(byYear.tailMap(2024));     // view from 2024 up

Map<String, Integer> revenue = new HashMap<>();
revenue.put("Danube View", 640);
revenue.put("City Inn", 180);
revenue.put("Alpen Hof", 380);

List<Map.Entry<String, Integer>> ranking = new ArrayList<>(revenue.entrySet());
ranking.sort(Map.Entry.<String, Integer>comparingByValue().reversed());

ranking.forEach(e -> System.out.println(e.getKey() + " = " + e.getValue()));

TreeSet<String> hotels = new TreeSet<>();
hotels.add("Danube View");
hotels.add("Alpen Hof");
hotels.add("Danube View");   // ignored, compare result is 0

System.out.println(hotels);        // [Alpen Hof, Danube View]
System.out.println(hotels.first()); // Alpen Hof
System.out.println(hotels.headSet("Danube View"));   // [Alpen Hof]

Queue<Booking> checkIn = new ArrayDeque<>();
checkIn.offer(new Booking("Anna", 3));
checkIn.offer(new Booking("Bela", 1));

Booking next = checkIn.poll();   // Anna, null when empty
Booking peeked = checkIn.peek(); // Bela, still queued
System.out.println(checkIn.size());   // 1

Deque<String> history = new ArrayDeque<>();
history.push("list");    // add to the front
history.push("map");
history.push("stream");

System.out.println(history.pop());     // stream
System.out.println(history.peek());    // map
System.out.println(history.size());    // 2

Iterator<Booking> it = bookings.iterator();
while (it.hasNext()) {
    Booking b = it.next();
    if (b.nights() == 0) {
        it.remove();   // legal removal through the iterator
    }
}

// A for-each loop would throw ConcurrentModificationException here.

Comparator<Booking> report = Comparator
        .comparing(Booking::city)
        .thenComparing(Booking::hotelName)
        .thenComparingInt(Booking::nights);

bookings.sort(report);

// Whole chain reversed: nights descending first.
bookings.sort(Comparator.comparingInt(Booking::nights).reversed());

List<String> labels = bookings.stream()
        .filter(b -> b.nights() >= 2)          // keep longer stays
        .map(b -> b.hotelName() + " " + b.nights())
        .collect(Collectors.toList());

System.out.println(labels);

int revenue = bookings.stream()
        .mapToInt(Booking::total)
        .sum();

double avgNights = bookings.stream()
        .mapToInt(Booking::nights)
        .average()
        .orElse(0);

System.out.println(revenue + " / " + avgNights);

Map<String, Long> countByCity = bookings.stream()
        .collect(Collectors.groupingBy(
                Booking::city,
                TreeMap::new,          // sorted keys
                Collectors.counting()));

System.out.println(countByCity);   // {Budapest=3, Praha=1, Vienna=1}

Optional<Booking> best = bookings.stream()
        .max(Comparator.comparingInt(Booking::total));

String label = best
        .map(b -> b.hotelName() + " = " + b.total())
        .orElse("no bookings");

System.out.println(label);

List<String> top = bookings.stream()
        .sorted(Comparator.comparingInt(Booking::total).reversed())
        .limit(3)
        .map(b -> b.hotelName() + " (" + b.total() + ")")
        .toList();

System.out.println(top);

IntSummaryStatistics stats = bookings.stream()
        .mapToInt(Booking::nights)
        .summaryStatistics();

System.out.println(stats.getCount());
System.out.println(stats.getSum());
System.out.println(stats.getMin() + " - " + stats.getMax());
System.out.printf("%.2f%n", stats.getAverage());
